package com.bank.merge.engine;

import java.util.*;
import java.util.logging.Logger;

// Models MERGE: matched→update/delete, not-matched→insert, in one pass.
public class MergeEngine {
    private static final Logger log = Logger.getLogger(MergeEngine.class.getName());

    public record FeedRow(String accountId, String status) {}

    // target: current status map; source: nightly feed.
    public void merge(Map<String, String> target, List<FeedRow> source) {
        for (FeedRow s : source) {
            boolean matched = target.containsKey(s.accountId());
            if (matched && "CLOSED".equals(s.status())) {
                target.remove(s.accountId());
                log.info(() -> "WHEN MATCHED + CLOSED → DELETE " + s.accountId());
            } else if (matched) {
                target.put(s.accountId(), s.status());
                log.info(() -> "WHEN MATCHED → UPDATE " + s.accountId() + "=" + s.status());
            } else {
                target.put(s.accountId(), s.status());
                log.info(() -> "WHEN NOT MATCHED → INSERT " + s.accountId() + "=" + s.status());
            }
        }
    }
}
