package com.bank.merge.engine;

import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// Models INSERT ... ON CONFLICT with a sequence that GAPS on conflict.
public class UpsertEngine {
    private static final Logger log = Logger.getLogger(UpsertEngine.class.getName());
    private final AtomicLong sequence = new AtomicLong(0);  // BIGSERIAL-like
    private final Map<String, Long> rows = new HashMap<>(); // key → id

    // Returns the row id; on conflict the drawn sequence value is wasted (a gap).
    public long upsert(String key) {
        long drawnId = sequence.incrementAndGet();          // consumed BEFORE conflict check
        if (rows.containsKey(key)) {
            long existing = rows.get(key);
            log.warning(() -> "CONFLICT on " + key + " → UPDATE existing id=" + existing
                    + "; sequence value " + drawnId + " WASTED (gap)");
            return existing;
        }
        rows.put(key, drawnId);
        log.info(() -> "INSERT " + key + " id=" + drawnId);
        return drawnId;
    }

    public long lastSequence() { return sequence.get(); }
}
