package com.bank.merge;

import com.bank.merge.engine.*;
import com.bank.merge.engine.MergeEngine.FeedRow;
import java.util.*;
import java.util.logging.*;

public class MergeDemo {
    private static final Logger log = Logger.getLogger(MergeDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();

        log.info("=== MERGE: reconcile account_status against nightly feed ===");
        Map<String,String> target = new HashMap<>();
        target.put("SAV2001","ACTIVE");          // existing, will be updated
        target.put("OLD9999","ACTIVE");          // existing, feed says closed → delete
        List<FeedRow> feed = List.of(
            new FeedRow("SAV2001","SUSPENDED"),   // matched → update
            new FeedRow("OLD9999","CLOSED"),       // matched + closed → delete
            new FeedRow("CUR3001","ACTIVE"));      // not matched → insert
        new MergeEngine().merge(target, feed);
        log.info("account_status after MERGE = " + target);

        log.info("=== ON CONFLICT upsert: watch the sequence gap ===");
        UpsertEngine up = new UpsertEngine();
        up.upsert("SAV2001|2026-10-25");   // insert id=1
        up.upsert("CUR3001|2026-10-25");   // insert id=2
        up.upsert("SAV2001|2026-10-25");   // conflict → update; id=3 WASTED
        up.upsert("NEW5005|2026-10-25");   // insert id=4 (notice id=3 is missing → gap)
        log.info(() -> "last sequence value = " + up.lastSequence() + " (ids used: 1,2,4; 3 is a gap)");
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

